unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic,
                                       unsigned long addr,
                                       unsigned long length)
{
    unsigned int reg = ioapic->ioregsel;

    switch (reg) {
    case KVM_IOAPIC_REG_SELECT_ID:
        return (ioapic->id << 8) | 0x10;

    case KVM_IOAPIC_REG_SELECT_VERSION:
        return (KVM_IOAPIC_VERSION << 8) | (KVM_IOAPIC_IRQ_NUM - 1);

    case KVM_IOAPIC_REG_SELECT_REDTBL_LOW ... KVM_IOAPIC_REG_SELECT_REDTBL_HIGH:
        if (reg < KVM_IOAPIC_REG_SELECT_REDTBL_LOW || reg > KVM_IOAPIC_REG_SELECT_REDTBL_HIGH)
            return 0;

        return ioapic->redir_table[(reg - KVM_IOAPIC_REG_SELECT_REDTBL_LOW) / 2];
        break;

    default:
        return 0;
    }
}

unsigned long kvm_ioapic_read_indirect_reg(struct kvm_ioapic *ioapic, unsigned long addr, unsigned long length)
{
    unsigned long val = 0;

    switch (ioapic->ioregsel) {
    case KVM_IOAPIC_REG_SELECT_ID:
        val = (ioapic->id << KVM_IOAPIC_REG_ID_SHIFT) | KVM_IOAPIC_DEFAULT_ID;
        break;
    case KVM_IOAPIC_REG_SELECT_VERSION:
        val = ((ioapic->num_redirtbl_entries & KVM_IOAPIC_REG_VERSION_NUM_MASK) << KVM_IOAPIC_REG_VERSION_NUM_SHIFT) |
              (KVM_IOAPIC_VERSION << KVM_IOAPIC_REG_VERSION_ID_SHIFT);
        break;
    case KVM_IOAPIC_REG_SELECT_REDIRECTION_TABLE:
        if (ioapic->ioregsel_index < ioapic->num_redirtbl_entries)
            val = ioapic->redirtbl[ioapic->ioregsel_index].bits;
        else
            val = KVM_IOAPIC_DEFAULT_REDIRECTION_TABLE_ENTRY;
        break;
    default:
        val = KVM_IOAPIC_DEFAULT_REGISTER_VALUE;
        break;
    }

    return val;
}

unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic,
				       unsigned long addr,
				       unsigned long length)
{
	unsigned long ret = 0;

	switch (ioapic->ioregsel) {
	case KVM_IOAPIC_REG_SELECT_VERSION:
		ret = (ioapic->id << 16) | (KVM_IOAPIC_VERSION_ID & 0xff);
		break;
	case KVM_IOAPIC_REG_SELECT_ID:
		ret = ioapic->id;
		break;
	case KVM_IOAPIC_REG_SELECT_REDTBL ... KVM_IOAPIC_REG_SELECT_REDTBL + KVM_IOAPIC_NUM_RT_REGS - 1:
		if (ioapic->ioregsel < KVM_IOAPIC_NUM_RT_REGS)
			ret = ioapic->regs.redtbl[ioapic->ioregsel];
		break;
	default:
		ret = 0;
		break;
	}

	return ret;
}

unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic, unsigned long addr, unsigned long length)
{
    unsigned long val = 0;

    switch (ioapic->ioregsel) {
    case KVM_IOAPIC_REG_SELECT_ID:
        val = ioapic->id << 2;
        break;
    case KVM_IOAPIC_REG_SELECT_VERSION:
        val = (KVM_IOAPIC_VERSION << 2) | KVM_IOAPIC_REVISION;
        break;
    case KVM_IOAPIC_REG_SELECT_RED_TBL_BASE ... KVM_IOAPIC_REG_SELECT_RED_TBL_BASE + 2 * KVM_IOAPIC_MAX_ENTRIES - 1:
        if (ioapic->ioregsel >= ioapic->nredir_tbl_entries * 2)
            break;
        if (ioapic->ioregsel & 0x1)
            val = ioapic->redir_entries[ioapic->ioregsel >> 1].low;
        else
            val = ioapic->redir_entries[ioapic->ioregsel >> 1].high;
        break;
    default:
        break;
    }

    return val;
}

unsigned long kvm_ioapic_read_indirect(struct kvm_ioapic *ioapic, unsigned long addr, unsigned long length)
{
    uint8_t reg = ioapic->ioregsel;

    if (reg == KVM_IOAPIC_REG_SELECT_VERSION_ID) {
        return (ioapic->id << 16) | (KVM_IOAPIC_VERSION << 8) | (KVM_IOAPIC_REVISION);
    } else if (reg == KVM_IOAPIC_REG_SELECT_ID) {
        return (ioapic->id << 16) | ioapic->id;
    } else if ((reg >= KVM_IOAPIC_REG_SELECT_REDIRECTION_TABLE) &&
               (reg <= KVM_IOAPIC_REG_SELECT_REDIRECTION_TABLE + KVM_IOAPIC_MAX_ENTRIES * 2 - 2)) {
        int index = (reg - KVM_IOAPIC_REG_SELECT_REDIRECTION_TABLE) / 2;
        if (index < KVM_IOAPIC_MAX_ENTRIES)
            return index % 2 ? ioapic->redir_entries[index].bits :
                               ioapic->redir_entries[index / 2].bits;
    }

    return 0;
}
